import { Mesh, PlaneGeometry, Group, Object3D, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} PrimitiveSpec
 * @property {string} name
 * @property {Object} params
 */

/**
 * @typedef {Object} NodeConfig
 * @property {Array<string|Object>} textContent
 * @property {Array<PrimitiveSpec>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives
 * @property {Object} fontAtlas
 */

/**
 * Create a ticker ribbon node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----- Root group ---------------------------------------------------------
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.name = 'TickerRibbonRoot';

  // ----- Ribbon plane (background) -----------------------------------------
  const PLANE_W = 7.0;
  const PLANE_H = 0.35;

  const planeGeom = new PlaneGeometry(PLANE_W, PLANE_H);
  const planeMat = new MeshStandardNodeMaterial({
    color: new Color('#111117'),
    roughness: 0.6,
    metalness: 0.2,
    // the plane itself does not need emissive or map; texture will be placed
    // by child meshes (text + tick marks)
  });

  const ribbonPlane = new Mesh(planeGeom, planeMat);
  ribbonPlane.name = 'RibbonPlane';
  root.add(ribbonPlane);

  // ----- Helper: tick mark --------------------------------------------------
  function createTickMark() {
    const tickW = 0.02 * PLANE_W; // relative to plane width
    const tickH = 0.14 * PLANE_H;
    const geom = new PlaneGeometry(tickW, tickH);
    const mat = new MeshStandardNodeMaterial({
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.5,
      roughness: 0.6,
      metalness: 0.0,
      side: 2, // DoubleSide
      transparent: true,
      opacity: 1.0,
    });
    const mesh = new Mesh(geom, mat);
    mesh.position.set(0, 0, 0.02); // slightly above the ribbon surface
    return mesh;
  }

  // ----- Build scrolling strip ---------------------------------------------
  const stripGroup = new Group();
  stripGroup.name = 'ScrollingStrip';

  /** @type {Array<string>} */
  const entries = Array.isArray(config.textContent) ? config.textContent : [];

  const GAP_UNITS = 0.5; // gap on both sides of each tick mark
  const CHAR_W_EST = 0.13; // rough estimate per character in scene units

  let cursorX = 0;

  entries.forEach((txt, idx) => {
    // Text mesh
    const textMesh = createTextMesh(txt, {
      fontSize: 13,
      fontWeight: 700,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
      family: 'JetBrains Mono',
      lineHeight: 1,
      letterSpacing: 0.06,
    });
    textMesh.position.set(cursorX, 0, 0.02);
    textMesh.name = `TickerText_${idx}`;
    stripGroup.add(textMesh);

    // Estimate width of the text (very rough)
    const estTextW = txt.length * CHAR_W_EST;

    // Advance cursor past text
    cursorX += estTextW;

    // Left gap
    cursorX += GAP_UNITS;

    // Tick mark
    const tick = createTickMark();
    tick.position.set(cursorX, 0, 0.02);
    tick.name = `TickMark_${idx}`;
    stripGroup.add(tick);

    // Right gap
    cursorX += GAP_UNITS;

    // Add extra spacing after each entry
    cursorX += GAP_UNITS;
  });

  const stripLength = cursorX;

  // Duplicate strip for seamless looping
  const stripClone = stripGroup.clone();
  stripClone.position.x = stripLength;
  stripClone.name = 'ScrollingStripClone';

  // Container that will be animated
  const scrollContainer = new Group();
  scrollContainer.name = 'ScrollContainer';
  scrollContainer.add(stripGroup);
  scrollContainer.add(stripClone);
  root.add(scrollContainer);

  // ----- Apply cinematic primitives -----------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(scrollContainer, prim.params);
      }
    });
  }

  // ----- User data ----------------------------------------------------------
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose ribbon plane
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose all text and tick meshes
    const disposeRecursive = (obj) => {
      obj.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    };
    disposeRecursive(root);

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
